__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"default",{enumerable:!0,get:function(){return o}});var t=r(d[0]),n=r(d[1]),c=r(d[2]);function o(){const o=(0,t.c)(1);let u;return o[0]===Symbol.for("react.memo_cache_sentinel")?(u=(0,c.jsx)(n.Terms,{}),o[0]=u):u=o[0],u}},782,[785,915,6]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),e.Terms=function(){const c=(0,s.c)(1);let p;c[0]===Symbol.for("react.memo_cache_sentinel")?(p=(0,n.jsx)(o.LegalPage,{title:"T\xe9rminos y condiciones",intro:`Estos t\xe9rminos regulan el uso de OfiApp, operada por ${t.LegalEntity.name}. L\xe9elos con calma: al usar la app los aceptas.`,sections:l}),c[0]=p):p=c[0];return p};var s=r(d[0]),o=r(d[1]),t=r(d[2]),n=r(d[3]);const l=[{title:'Qu\xe9 es OfiApp',body:['OfiApp es una plataforma que conecta a personas que necesitan un servicio (clientes) con personas que lo ofrecen (prestadores), como plomeros, electricistas, t\xe9cnicos, personal de aseo o animadores.','OfiApp no presta los servicios, no es empleador de los prestadores y no es parte de los acuerdos entre clientes y prestadores. El precio, la fecha, la calidad y las condiciones de cada trabajo los acuerdan directamente ellos.']},{title:'Tu cuenta',body:['\u2022 Debes ser mayor de 18 a\xf1os y dar informaci\xf3n veraz.','\u2022 Tu cuenta es personal. Eres responsable de lo que se haga con ella; si crees que alguien m\xe1s la est\xe1 usando, av\xedsanos.','\u2022 Al usar OfiApp aceptas estos t\xe9rminos y la Pol\xedtica de tratamiento de datos personales.']},{title:'Si ofreces servicios',body:['\u2022 La informaci\xf3n de tu perfil debe ser real: tu nombre, tus servicios, tu experiencia y tus fotos de trabajos propios.','\u2022 Eres responsable de contar con los permisos, licencias o certificaciones que exija tu oficio, y de cumplir tus obligaciones tributarias y laborales.','\u2022 Debes cumplir lo que acuerdes con tus clientes y tratarlos con respeto.','\u2022 Los sellos de verificaci\xf3n indican que revisamos los documentos que enviaste en una fecha determinada. No son una garant\xeda de tu trabajo ni de tu conducta futura.']},{title:'Si contratas servicios',body:['\u2022 Antes de iniciar un trabajo, acuerda con el prestador el precio, la fecha y lo que incluye, idealmente por escrito.','\u2022 Revisa las rese\xf1as y los sellos de verificaci\xf3n, y usa tu criterio al elegir.','\u2022 Solo quienes contactaron a un prestador desde OfiApp pueden calificarlo. Tu rese\xf1a debe ser honesta y basada en tu experiencia real.']},{title:'Pagos y OfiApp Pro',body:['OfiApp es gratis para clientes y prestadores. OfiApp no recibe ni procesa los pagos de los servicios: se hacen directamente entre cliente y prestador.','OfiApp Pro es un plan opcional para prestadores con beneficios adicionales. Si en alg\xfan momento tiene costo, te informaremos el precio y las condiciones antes de cobrarte.']},{title:'Lo que no est\xe1 permitido',body:['\u2022 Publicar informaci\xf3n falsa, suplantar a otra persona o usar documentos ajenos.','\u2022 Ofrecer servicios ilegales o peligrosos.','\u2022 Acosar, amenazar, discriminar o insultar a otros usuarios.','\u2022 Publicar rese\xf1as falsas o pagar por ellas.','\u2022 Enviar publicidad no solicitada o usar los datos de otros usuarios para fines distintos a contratar un servicio.','\u2022 Intentar acceder a cuentas ajenas o afectar el funcionamiento de la app.']},{title:'Rese\xf1as, reportes y moderaci\xf3n',body:['Puedes reportar perfiles o conductas que incumplan estos t\xe9rminos. Revisamos los reportes y podemos ocultar contenido, pausar perfiles o cerrar cuentas que los incumplan, sin perjuicio de las acciones legales que correspondan.']},{title:'Tu contenido',body:['Lo que publicas (fotos, textos, rese\xf1as) sigue siendo tuyo. Nos das permiso para mostrarlo dentro de OfiApp y en los enlaces p\xfablicos de perfiles mientras tengas tu cuenta. Debes tener derecho a publicar ese contenido.']},{title:'Responsabilidad',body:['Hacemos lo posible para que OfiApp funcione bien y sea segura, pero no podemos garantizar que est\xe9 siempre disponible ni sin errores. Como no somos parte de los acuerdos entre usuarios, no respondemos por la calidad, el resultado o el pago de los servicios contratados, ni por los da\xf1os que se causen entre ellos.','Nada de lo anterior limita los derechos que te da la Ley 1480 de 2011 (Estatuto del Consumidor) frente a los servicios que OfiApp te presta directamente.']},{title:'Terminaci\xf3n',body:[`Puedes dejar de usar OfiApp cuando quieras y pedir que eliminemos tu cuenta escribiendo a ${t.LegalEntity.email}. Si eres prestador, tambi\xe9n puedes pausar tu perfil desde la app.`]},{title:'Cambios y ley aplicable',body:['Podemos actualizar estos t\xe9rminos. Si el cambio es importante, te avisaremos en la app antes de que aplique. Estos t\xe9rminos se rigen por las leyes de la Rep\xfablica de Colombia.']}]},915,[785,867,859,6]);